#define main historical_main
#include "../concat-cuda/main.cu"
#undef main
#include <vector>
#include <cmath>
#define CK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
struct Case{float*a,*b,*c;std::vector<float>expected;int sz0,sz2,s1,s2;};
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):100;if(repeat<1)return 2;std::vector<Case>cases;for(int heads:{6,12,24,48}){Case c;c.sz0=2*heads;c.sz2=128;srand(heads);c.s1=rand()%31+1;c.s2=32-c.s1;int n1=c.sz0*128*c.s1,n2=c.sz0*128*c.s2;std::vector<float>a(n1),b(n2);for(float&x:a)x=rand()%n1;for(float&x:b)x=rand()%n2;c.expected.resize(n1+n2);concat_cpu(a.data(),b.data(),c.expected.data(),c.sz0,c.sz2,c.s1,c.s2);CK(cudaMalloc(&c.a,n1*sizeof(float)));CK(cudaMalloc(&c.b,n2*sizeof(float)));CK(cudaMalloc(&c.c,c.expected.size()*sizeof(float)));CK(cudaMemcpy(c.a,a.data(),n1*sizeof(float),cudaMemcpyHostToDevice));CK(cudaMemcpy(c.b,b.data(),n2*sizeof(float),cudaMemcpyHostToDevice));concat<<<(c.expected.size()+255)/256,256>>>(c.a,c.b,c.c,c.sz0,c.sz2,c.s1,c.s2);cases.push_back(c);}CK(cudaDeviceSynchronize());bool allok=true;
for(int trial=1;trial<=5;trial++){std::vector<float>out;double seconds=0,times[4],ma=0;bool ok=true;int ci=0;for(auto&c:cases){CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int rep=0;rep<repeat;rep++)concat<<<(c.expected.size()+255)/256,256>>>(c.a,c.b,c.c,c.sz0,c.sz2,c.s1,c.s2);CK(cudaDeviceSynchronize());times[ci++]=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;seconds+=times[ci-1];std::vector<float>got(c.expected.size());CK(cudaMemcpy(got.data(),c.c,got.size()*sizeof(float),cudaMemcpyDeviceToHost));for(int i=0;i<(int)got.size();i++){ma=fmax(ma,fabs(got[i]-c.expected[i]));ok&=std::isfinite(got[i])&&got[i]==c.expected[i];}out.insert(out.end(),got.begin(),got.end());}allok&=ok;char file[80];sprintf(file,"concat_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(out.data(),sizeof(float),out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":0,\"timing_region\":\"sum_four_head_count_concat_operations_transfer_excluded\",\"jit_excluded\":true,\"internal_repeats\":%d,\"head_count_times_seconds\":[%.12g,%.12g,%.12g,%.12g],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",out.size(),ma,repeat,times[0],times[1],times[2],times[3],file,out.size());}for(auto&c:cases){CK(cudaFree(c.a));CK(cudaFree(c.b));CK(cudaFree(c.c));}puts(allok?"PASS":"FAIL");return allok?0:1;}
